# -*- coding: utf-8 -*-
"""Actualizador de reportes semanales (PlusMetas · MF)."""
import os
import streamlit as st
import pptx_updater, convenios_updater, campanias_updater

st.set_page_config(page_title="Reportes semanales · PlusMetas · MF", page_icon="📊", layout="centered")
BASE=os.path.dirname(os.path.abspath(__file__))
MIME="application/vnd.openxmlformats-officedocument.presentationml.presentation"

st.markdown('\n<style>\n#MainMenu, header[data-testid="stHeader"], footer {visibility:hidden; height:0;}\n.stApp { background:#EDF1F5; }\n.block-container { padding-top:1.0rem; max-width:860px; }\n.hero { background:linear-gradient(105deg,#123f60 0%,#145078 40%,#54241f 63%,#6B150B 100%);\n    border-radius:14px; padding:18px 26px 20px; position:relative; overflow:hidden;\n    box-shadow:0 8px 24px rgba(0,0,0,.22); }\n.hero::after { content:""; position:absolute; left:0; right:0; bottom:0; height:5px;\n    background:linear-gradient(90deg,#AFCB07 0%,#AFCB07 50%,#D3141B 50%,#D3141B 100%); }\n.hero-logos { display:flex; justify-content:space-between; align-items:center; margin-bottom:12px; }\n.hero-logos img.pm { height:32px; } .hero-logos img.mf { height:30px; }\n.hero h1 { color:#fff; margin:0; font-size:23px; font-weight:800; }\n.hero p { color:#d3dfea; margin:6px 0 0; font-size:12px; font-weight:600; letter-spacing:.6px; }\n.step { margin:20px 0 8px; font-size:15px; font-weight:800; color:#145078;\n    border-left:5px solid #AFCB07; padding:2px 0 2px 11px; }\n.stButton>button, .stDownloadButton>button { background:#145078; color:#fff; border:0;\n    border-radius:10px; padding:.62rem 1rem; font-weight:700; font-size:15px; transition:.15s; }\n.stButton>button:hover, .stDownloadButton>button:hover { background:#6B150B; color:#fff; }\n.stButton>button:disabled { background:#C6D0DA; color:#eef3f8; }\n[data-testid="stFileUploaderDropzone"] { background:#F7FAFC; border:1.6px dashed #B7C5D3; border-radius:11px; }\n[data-testid="stFileUploaderDropzone"] button { background:#fff; color:#145078; border:1px solid #145078; border-radius:8px; font-weight:600; }\ndiv[role="radiogroup"] label { font-weight:600; color:#145078; }\n.brandfoot { text-align:center; color:#9aa8b5; font-size:11px; margin-top:28px; }\n</style>\n', unsafe_allow_html=True)
st.markdown('<div class="hero"><div class="hero-logos"><img class="pm" src="data:image/png;base64,"/><img class="mf" src="data:image/png;base64,"/></div><h1>Actualizador de Reportes Semanales</h1><p>PLUSMETAS &nbsp;·&nbsp; MF ASESORÍA Y CONSULTORÍA</p></div>', unsafe_allow_html=True)

st.markdown('<div class="step">Elige el reporte a actualizar</div>', unsafe_allow_html=True)
modo=st.radio("modo", ["Comité de Campañas (consolidado · 2 Excel)","Reporte TLM (1 Excel)","Reporte Convenios (1 Excel)"], label_visibility="collapsed")

def run_single(motor, plantilla, tipo, data):
    with st.spinner("Generando…"):
        pptx,res,warns=motor.update_presentation(open(os.path.join(BASE,plantilla),"rb").read(), data)
    st.success(f"Presentación lista · Periodo {res['mes']}.")
    for w in warns: st.warning(w)
    st.download_button("⬇  Descargar PowerPoint", pptx, file_name=f"{tipo}_{res['periodo']}.pptx", mime=MIME, type="primary", use_container_width=True)

if modo.startswith("Comité"):
    st.markdown('<div class="step">Paso 1 · Excel de Campañas / Telemarketing</div>', unsafe_allow_html=True)
    f_camp=st.file_uploader("camp", type=["xlsx","xlsm"], key="camp", label_visibility="collapsed")
    st.markdown('<div class="step">Paso 2 · Excel de Convenios</div>', unsafe_allow_html=True)
    f_conv=st.file_uploader("conv", type=["xlsx","xlsm"], key="conv", label_visibility="collapsed")
    st.markdown('<div class="step">Paso 3 · Día de corte</div>', unsafe_allow_html=True)
    st.caption("Día hasta el que llega la información (todas las fechas del PPT dirán \u201cavance al día X\u201d).")
    dia_corte=st.number_input("Día de corte", min_value=1, max_value=31, value=5, step=1, label_visibility="collapsed")
    ready=(f_camp is not None) and (f_conv is not None)
    if not ready: st.caption("Sube los dos Excel para habilitar el botón.")
    if st.button("Generar presentación consolidada", type="primary", disabled=not ready, use_container_width=True):
        try:
            with st.spinner("Actualizando todas las unidades…"):
                tpl=open(os.path.join(BASE,"plantilla_campanias.pptx"),"rb").read()
                camp_bytes=f_camp.read(); conv_bytes=f_conv.read()
                try:
                    pptx,res,warns=campanias_updater.update_presentation(tpl, camp_bytes, conv_bytes, dia_override=int(dia_corte))
                except TypeError:
                    pptx,res,warns=campanias_updater.update_presentation(tpl, camp_bytes, conv_bytes)
                    st.warning("El motor desplegado es una versión anterior (sin 'día de corte'). Sube el campanias_updater.py más reciente y reinicia la app.")
            st.success(f"Presentación lista · Periodo {res['mes']} (al día {res['dia']}).")
            for w in warns: st.warning(w)
            st.download_button("⬇  Descargar PowerPoint", pptx, file_name=f"campanias_{res['periodo']}.pptx", mime=MIME, type="primary", use_container_width=True)
        except Exception as e:
            import traceback; st.error(f"Error: {e}"); st.code(traceback.format_exc())
elif modo.startswith("Reporte TLM"):
    st.markdown('<div class="step">Excel TLM</div>', unsafe_allow_html=True)
    f=st.file_uploader("tlm", type=["xlsx","xlsm"], key="tlm", label_visibility="collapsed")
    if f is not None and st.button("Actualizar presentación", type="primary", use_container_width=True):
        run_single(pptx_updater,"plantilla_tlm.pptx","tlm",f.read())
else:
    st.markdown('<div class="step">Excel de Convenios</div>', unsafe_allow_html=True)
    f=st.file_uploader("cv", type=["xlsx","xlsm"], key="cv", label_visibility="collapsed")
    if f is not None and st.button("Actualizar presentación", type="primary", use_container_width=True):
        run_single(convenios_updater,"plantilla_convenios.pptx","convenios",f.read())
st.markdown('<p class="brandfoot">PlusMetas &nbsp;·&nbsp; MF Asesoría y Consultoría &nbsp;—&nbsp; Tu meta es nuestra meta</p>', unsafe_allow_html=True)
